                    {
                        "type": "char_exclude",
                        "value": [
                            [
                                ord("A"),
                                ord("Z"),
                            ],
                        ],
                    },
                ],
            ),
            (
                "root ::= [^A-Z0-9]",
                [
                    {
                        "type": "char_exclude",
                        "value": [
                            [
