            ),
            # expression and a char rule
            (
                '''
root ::= foo | "bar"
foo ::= "foo"''',
                [
                    {
                        "type": "char",
                        "value": [ord("f")],
                    },
                    {
                        "type": "char",
                        "value": [ord("b")],
                    },
                ],
            ),
            # two expressions
            (
                """
root ::= foo | bar
foo ::= "foo"
bar ::= "bar"
  """,
                [
                    {
                        "type": "char",
                        "value": [ord("f")],
                    },
                    {
                        "type": "char",
                        "value": [ord("b")],
                    },
                ],
            ),
