                """
root ::= f | b
f ::= fo
b ::= ba
fo ::= foo
ba ::= bar | baz
foo ::= "foo"
bar ::= "bar"
baz ::= "baz"
  """,
                [
                    {
                        "type": "char",
                        "value": [ord("f")],
                    },
                    {
                        "type": "char",
                        "value": [ord("b")],
                    },
                ],
            ),
            # ranges
            (
                "root ::= [a-z]",
                [
                    {
                        "type": "char",
                        "value": [[ord("a"), ord("z")]],
                    },
