                    },
                ],
            ),
            # range with ? modifier
            (
                "root ::= [a-z]?",
                [
                    {
                        "type": "char",
                        "value": [[ord("a"), ord("z")]],
                    },
                    {
                        "type": "end",
                    },
                ],
            ),
            # range with + modifier
