  get id(): string {
    if (this.#id === undefined) {
      const { stackId, pathId, stepId } = this.meta;
      this.#id = `${stackId},${pathId},${stepId}`;
    }
    return this.#id;
  }

  print(opts: PrintOpts): string {
    return printGraphNode(this)(opts);
  }
}

