"""Dump the parametrize data out of the python test suite as JSON.

The ported (vitest) suite consumes these fixtures so that it exercises exactly
the same cases, in the same order, as tests/python.
"""

import json
import runpy
import sys
import types
from pathlib import Path

SRC = Path("/workspace/tests/python")
OUT = Path("/workspace/ported_implementation/tests/fixtures")

captured: list[dict] = []


class _Mark:
    def parametrize(self, argnames, argvalues, **_kwargs):
        if isinstance(argnames, str):
            names = [n.strip() for n in argnames.split(",")]
        else:
            names = list(argnames)

        def deco(func):
            captured.append(
                {
                    "test": func.__name__,
                    "argnames": names,
                    "argvalues": [
                        list(v) if isinstance(v, (list, tuple)) else [v]
                        for v in argvalues
                    ],
                }
            )
            return func

        return deco


class _Pytest(types.ModuleType):
    mark = _Mark()

    @staticmethod
    def raises(*_args, **_kwargs):
        raise AssertionError("raises should not run during extraction")

    @staticmethod
    def fixture(*args, **kwargs):
        def deco(func):
            return func

        return deco(args[0]) if args and callable(args[0]) else deco


class _Gbnf(types.ModuleType):
    GBNF = object
    RuleChar = object
    RuleCharExclude = object
    RuleEnd = object
    InputParseError = object
    GrammarParseError = object


sys.modules["pytest"] = _Pytest("pytest")
sys.modules["gbnf"] = _Gbnf("gbnf")

OUT.mkdir(parents=True, exist_ok=True)

for path in sorted(SRC.rglob("*_test.py")):
    captured.clear()
    globs = runpy.run_path(str(path))
    for name, value in globs.items():
        if name.startswith("describe_") and callable(value):
            value()
    if not captured:
        continue
    out = {entry["test"]: entry for entry in captured}
    target = OUT / f"{path.stem}.json"
    target.write_text(json.dumps(out, indent=2, ensure_ascii=False) + "\n")
    total = sum(len(e["argvalues"]) for e in captured)
    print(f"{target.name}: {len(captured)} parametrized tests, {total} cases")

